import{_ as p,c as e,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"中孚","description":"高島易斷 - 中孚","frontmatter":{"title":"中孚","description":"高島易斷 - 中孚"},"headers":[],"relativePath":"classics/takashima/061.md","filePath":"classics/takashima/061.md"}'),i={name:"classics/takashima/061.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="中孚" tabindex="-1">中孚 <a class="header-anchor" href="#中孚" aria-label="Permalink to “中孚”">​</a></h1><h2 id="中孚-1" tabindex="-1">中孚 <a class="header-anchor" href="#中孚-1" aria-label="Permalink to “中孚”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>中孚：豚魚吉，利涉大川，利貞。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>孚者，信也，“中孚”者，信發於中也。內卦《兌》，《睽》上曰“豕負塗”，“塗”謂《兌》澤虧下，足以牧豕，豕小為豚，故《兌》亦有豚象；外卦《巽》，《巽》為魚，魚得水澤以為樂。二物雖微，皆能得《巽》《兌》之性，以為生活，故曰“豚魚吉。”“大川”，即澤之大者。《巽》為木，“刳木為舟”，是涉川者所利用也，故曰“利涉大川”。其孚如此，宜無往而不利矣，然其中之邪正誠偽，又不可不辨，故曰“利貞”。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>澤上有風，中孚。君子以議獄緩死。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>《象》不曰風在澤上，而曰“澤上有風”，顯見澤水本靜，因風而生波，猶言人心本平，因爭而速獄。《巽》曰“申命”，有議緩之象；《兌》為刑人，有死獄之象；卦下互《震》，《震》為議為生，為緩，有“議獄緩死”之象。呂刑曰，獄成而孚，是獄必孚乃定；然獄雖孚，猶必議而緩之，即所謂罪疑惟輕是也。“議獄”者，審其所可疑，“緩死”者，求其所以生，孚之至也，故曰“君子以議獄緩死”。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：“澤上有風”，防有風波之險。</p><p>○　問營商：宜仔細酌議，寬緩行事，斯得免害。</p><p>○　問戰徵：當以不嗜殺人為心，斯為心鹹孚，所向無敵。</p><p>○　問功名：一時罪獄未平，功名難望。</p><p>○　問婚姻：婚媾致寇，因之速獄，宜慎。</p><p>○　問家宅：主有訟獄之災。</p><p>○　問疾病：危則危矣，一時生命可保。</p><p>○　問訟事：一時未了。</p><p>○　問六甲：生女。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>“虞”，虞人也。《巽》四曰“田獲三品”，《兌》五曰“孚於剝”，《月令》，“冬日剝陰木”，《詩》雲“九月剝棗，是謂斬木”，是《巽》《兌》皆有虞人之象，故《中孚》初爻取之。王制獺祭魚，然後虞人入澤梁。按虞人入澤梁，在十月中，《周禮》山虞令萬民斬材木，《賈疏》“草木零落，然後入山林”，亦在十月中。《中孚》為十一月卦，正當入澤梁，斬材木時也。歲有常期，則漁者樵者，受命於虞人，入澤入林，各從其取，故曰“虞吉”。順《中孚》之時，不愆其候，不紛其志，無他求也；有他則上下不孚，漁樵失時，焚林竭澤，將自此起，不能安矣，故曰“有它不燕”，“燕”，安也。《象傳》以“志未變”釋“虞吉”，謂變即有他，有他即不吉矣。惟其初“志未變”，是以吉也。</p><h2 id="初九佔" tabindex="-1">初九佔 <a class="header-anchor" href="#初九佔" aria-label="Permalink to “初九佔”">​</a></h2><p>○　問時運：陽剛當令，用心專一，不惑於他途，故吉。</p><p>○　問營商：安於本業，見異不遷，以交冬令為利。</p><p>○　問功名：有志竟成。</p><p>○　問戰徵：《巽》初爻曰“利武人之貞”，從禽從戎，其義相同，所當專心一志，踴躍前進，自可獲勝。吉。</p><p>○　問婚姻：有從一而終之象。</p><p>○　問疾病：病可無虞，但恐有他變，變則危矣。</p><p>○　問訟事：恐有別生枝節。</p><p>○　問六甲：生女。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>友人某來，請佔商業，筮得《中孚》之《渙》。</p><p>斷曰：爻曰“虞吉”，“虞”謂虞人。《巽》為魚，兌為澤，故有虞人入澤梁之象。虞人入澤，得其所取，故吉，若他有所求，則取非其時，故不安。今足下佔商業，得此爻辭，知所謀之業，必近木近澤，所謀之人，皆已眾志相孚。事在初起，不必他求，業無不成。獲利以冬季為宜，足下安心從事可也。</p><h2 id="九二解" tabindex="-1">九二解 <a class="header-anchor" href="#九二解" aria-label="Permalink to “九二解”">​</a></h2><p>“鶴鳴”“子和”，喻《中孚》之相應也。鶴為陽鳥，二以陽處陰，故曰“在陰”。《春秋·說題》稱，鶴夜半則鳴，亦為信鳥，有孚之象。蓋鳴者在鶴，和者為子，一鳴一和，同聲相應，同氣相孚，有得《中孚》感應之妙者矣。“我”謂二，“爾”謂五，“我有好爵，吾與爾靡之”，“靡”，共也，為二得此“好爵”，願與五共之。二五相應，志同道合，一如母子相依，有同鳴共棲之象，其至誠之感孚如此。或疑五為君位，不當言子，不知《易》尚變通，未可拘執一見也。《象傳》曰，“中心願也”，謂鳴和乃自然之應，中心相孚，孚之至也。</p><h2 id="九二佔" tabindex="-1">九二佔 <a class="header-anchor" href="#九二佔" aria-label="Permalink to “九二佔”">​</a></h2><p>○　問時運：此唱彼和，適得我願，正當運途亨通之會。</p><p>○　問營商：主客同心，氣誼相投，有交相獲利之象。</p><p>○　問功名：有父子同升之庚。</p><p>○　問戰徵：上下一體，如以臂使手，以手使指，一氣相連，有進則共進，退則共退之象，未易攻擊者。</p><p>○　問婚姻：得夫婦唱隨之樂。</p><p>○　問疾病：是傳染之症。</p><p>○　問家宅：必是貴顯之家，且得孝賢之子。</p><p>○　問六甲：生女。</p><h2 id="九二案例" tabindex="-1">九二案例 <a class="header-anchor" href="#九二案例" aria-label="Permalink to “九二案例”">​</a></h2><p>某貴顯傷偶，鰥居數年，友人屢勸續娶不聽，一日聞岐阜縣士族，有一良婦，友人皆願為執斧，恐某貴顯固執不從，先為一筮以決之。筮得《中孚》之《益》。</p><p>斷曰：此爻曰“鳴”曰“和”，有兩心相得，同聲同應之象。卦名《中孚》，孚謂鳥抱卵，有育子之象。佔娶婦得此爻辭，知娶得此婦，必能夫唱婦隨，家室和平，“鶴鳴”“子和”，“好爵”“爾靡”；且他日其子又能繼承父業，共享榮貴，可謂既得佳婦，又有佳兒也，大吉之兆。佔得此爻，友人又懼某貴顯嚴肅，未敢啟齒，餘又佔其媒之成否，筮得《兌》之《隨》。爻辭曰：“九二：孚兌，吉，悔亡。”斷曰：得此爻，其成必矣。孚者，信也，《兌》者，悅也，既信且悅，復又何疑？餘乃先往說，果得允諾。繼而又有以閥閱一婦為媒者，或疑前約，將有更變，餘再筮之，遇《履》之《睽》。爻辭曰：“九五：夬履，貞厲。”斷曰：《履》之三爻，為“虎尾”，五爻為虎背也。今某貴顯騎虎之勢，有不能中止之象，且五爻《象傳》曰“夬履，位正當也”，是前約之婦，可為正婚也，知前約之婦，必不能罷。友人不聽，進告貴顯，貴顯決意不允，準從前約，因類記之。</p><p>明治三十年，佔我國與美國交際，筮得《中孚》之《益》。</p><p>斷曰：“鶴鳴”“子和”者，是謂母子相依，鳴聲相和，好爵爾靡者，是謂天爵之尊，爾我共有，此中相親相愛之情，中懷固結，有默相感召者也。今佔我國與美國交際，得此爻象，知我二邦，幫交素篤，雖遠隔重洋，渾如父子兄弟，共處一室，爾愛我憐，無詐無虞，各保天位，共修天爵。此後交際，當有益見親睦也。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>《易》例以俱剛俱柔謂敵應，此爻三四俱柔，敵體也，故曰“得敵”。二至四互《震》，《震》為鼓，又互《艮》，《艮》為止，止即罷也，故曰“或鼓，或罷”。《兌》為口，能歌，《巽》為號，象泣，故曰“或泣，或歌”。“或”者不定之辭，蓋三與四敵，始怒而鼓，復懼而罷，繼喜而歌，復悲而泣，皆由中心無主，言動改常，其象有如此者。夫人有孚，雖千里相應，孰非吾與？不孚，雖一室相違，皆為吾敵，固不在外貌之相親，而在內心之相孚也。三居《兌》之極，悅不由衷，故進退無極，憊可知也。《象傳》以“位不當”釋之，謂三以陰居陽，位不當也。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：目下運途顛倒。</p><p>○　問營商：忽盈忽虧，忽成忽敗，皆由主謀不定。</p><p>○　問功名：升降無常，榮辱隨之。</p><p>○　問戰徵：強敵在前，難以制勝。</p><p>○　問婚姻：反覆未成。</p><p>○　問家宅：宅神不安，事多顛倒。</p><p>○　問疾病：時重時輕，防有鬼祟。</p><p>○　問行人：欲歸復止，一時未定。</p><p>○　問失物：防得而復失。</p><p>○　問六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>知友某出仕某縣，頃有書來，曰奉內命，得升一級，自憾才力不能勝任，不如仍居現職，諸事熟練，僚友同心，幸無曠誤也，請煩一佔。筮得《中孚》之《小畜》。</p><p>斷曰：爻以敵應在前，以致進退無恆，哀樂不定，有得不足喜，失不足憂之象。今足下佔宦途升遷，得此爻象，知足下近有晉級之喜，然其中尚有轉折可慮。爻辭所謂“鼓”者進也，“罷”者退也，“泣”者悲也，“歌”者樂也，是明言時事顛倒，心神繚亂，必有忌者為之播弄於其間也。是謂“得敵”，故雖升遷，不如不調，仍服原職為是。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>六四重陰之爻，月，陰也，故象取月。月至“幾望”而始盈，盈則中實，有孚之象。四與五比，五為君位，日也，四為月，月無光，得日之光以為光，是日月交孚也，孚之正者也，故曰“月幾望”。“馬”者，卦體本《乾》，《乾》為馬，四動成《巽》，《乾》象已失，故曰“馬匹亡”。“匹”謂初，以四與初，以類相應，謂之匹。《巽》為風，馬之良者，能追風，《中孚》十一月，正胡馬感北風之時，是《中孚》之氣候，有以感之也。《象》以“絕類上也”釋“馬匹亡”，“類初”也。初亦《乾》體，象馬，如馬之離其群匹，絕初之類而上五也。“月幾望”者，無盈滿之嫌，“馬匹亡”者，無黨同之累，夫復何咎？竊又別得一說，按馬得月之精氣而生，月與馬自相感孚，故月馬並言。“幾望”者，為月盈滿之時，“匹亡”者，即《傳》所謂“絕類”，是馬之至良至馴者也。四爻重陰得《坤》氣，《坤》為月，亦為牝馬，爻象兼取之，以其一氣相孚也。亦足備解。</p><h2 id="六四佔" tabindex="-1">六四佔 <a class="header-anchor" href="#六四佔" aria-label="Permalink to “六四佔”">​</a></h2><p>○　問時運：運當全盛，宜保泰持盈，去私從公，得以無咎。</p><p>○　問營商：“月幾望”，喻財利之豐盈；“馬匹亡”，喻謀事之快利。吉。</p><p>○　問功名：有春風得意之象。</p><p>○　問戰徵：宜於月夜進攻，馬脫蹄，兵銜枚，奮勇而上，定可獲勝。</p><p>○　問婚姻；願望頗豐，“匹亡”者，恐不久有喪偶之災。</p><p>○　問疾病：三五之期不利。</p><p>○　問家宅：此宅陰氣太盛，恐同居中，難免死亡之禍。</p><p>○　問行人：十四五可歸。</p><p>○　問六甲：生女。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>縉紳某來，請佔謀事，筮得《中孚》之《履》。</p><p>斷曰：爻象取月，取馬，月則乘時而滿，馬者絕塵而趨，是為全盛之象。今足下佔謀事，得《中孚》四爻，知足下所謀之事，約在望前可以成就。惟一時同謀諸友，其間有性情契合者，亦有意氣不投者，所謂風馬牛之不相及也。宜以其不投者，絕謝之，使不致敗乃事矣，故無咎也。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>九五為孚之主，有孚一言，惟五足以當之。《巽》為繩，五《艮》為手，象攣，五居君位，二為臣位，五與二相應，即與二相孚。孚曰“攣如”，孚之至也。孚於臣，孚於民，亦可孚於邦，《彖》所謂“孚乃化邦”，由是而暨焉。《小畜》五爻，亦曰“有孚攣如”，《中孚》與《小畜》，同體巽順，故同象。《象傳》以“位正當”釋之，謂二五之位適當，是以牽繫不絕，故能有孚如此。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問時運：所謀所求，無不稱心。</p><p>○　問營商：同心協力，合夥經營，無不獲利。</p><p>○　問功名：有求必成。</p><p>○　問戰徵：軍心團結，戮力同心，自能制勝。</p><p>○　問婚姻：有二人同心，百年好合之慶。</p><p>○　問家宅：一家和樂，百室盈止。</p><p>○　問疾病：病由肝風，致手足牽攣，帶病延年，尚無咎也。</p><p>○　問訟事：防有桎梏之災。</p><p>○　問六甲：生女。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>縉紳某來，請佔婚，筮得《中孚》之《損》。</p><p>斷曰：卦象為至誠感孚，心心相印，故曰《中孚》。五爻為卦之主，爻曰“攣如”。正見其相孚之情，有團結而不解者矣。今佔婚姻，得此爻象，知兩家必是素相契合，有如手如足之好，此番締姻，自然夫唱婦隨，莫不靜好。且五為貴爻，亦必是名門閥閱之家，大喜。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>雞曰翰音，雞必振羽而復鳴。翰，羽翮也，雞鳴不失時，孚之象也。雞本微物，而翰音遠聞，人無實德，而有虛聲者似之。上居孚極，區區小忠小信，上徹九天，雖正亦兇。《象傳》釋以“何可長也”，謂其繩盜虛聲，何能久乎？</p><h2 id="上九佔" tabindex="-1">上九佔 <a class="header-anchor" href="#上九佔" aria-label="Permalink to “上九佔”">​</a></h2><p>○　問時運：運途亦盛，但虛而無實，轉覺可危。</p><p>○　問營商：場面頗廣，聲勢亦宏，有外觀而無內蘊，恐其不能久也。</p><p>○　問功名：繩盜靈聲，君子所恥。</p><p>○　問婚姻：恐難偕老。</p><p>○　問家宅：此宅有牝雞司晨之象，家業難保，兇。</p><p>○　問疾病：肝風作痛，喊叫聲聲，病狀頗苦，兇。</p><p>○　問訟事：勢將上控，兇。</p><p>○　問六甲：生女，小兒善啼，恐難育。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>一日有自稱天爵大神者來，餘問其名之何來，並相訪之意，彼曰：餘愛知縣士族也，為患道路險惡，行者苦之，乃攜鍬一挺，出東海道，獨力修繕，凡至一鄉，呼告村人，使鹹相助力，率以為常。一日山田大臣經過其地，見餘修路，促使相見，餘乃陳述心願，大臣贊之曰：忘身而圖公益者，謂之天爵大神，餘因之自號為天爵大神。問其來意，曰：今欲架一橋，勸募資助，餘乃以金若干與之。大神又請佔氣運，筮得《中孚》之《節》。</p><p>斷曰：一鳴而聲聞於天者，鶴也，雞乃家禽，而妄竊鳴鶴之聲，繩盜虛聲，恐幹災禍，故爻曰“貞兇”。今君佔氣運，得此爻象，適與君之作為，如合符節。君以苦心苦力，修繕道路，事非不正也，然好名之心太重，實欲藉此區區勞力，以博美譽。試觀水無源者立涸，木無根者立枯，名而無實，其安能不敗乎？且君稱名駭異，即取禍之由也。須斂跡自晦，可以免害。</p>',110)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
